gallery=head('Ten Directions','explore.css')+'''<body class="exploration"><header class="lab-header lab-wrap"><a class="lab-brand" href="/">east bay projects.<span>Design exploration</span></a><span class="test-label"><i></i> Test site · Production unchanged</span></header><main class="lab-wrap"><section class="lab-intro"><div><p class="lab-kicker">A study in ten directions / September 2026</p><h1>One studio.<br><em>Ten possibilities.</em></h1></div><div class="lab-intro-copy"><p>The same agency. Ten different ways to express it.</p><p>Explore complete pages, shortlist what feels right, and compare two directions side by side. Each brings businesses, founders, and civic work into one story.</p><a href="/editorial/" class="lab-start">Start exploring <span>↗</span></a></div></section><div class="gallery-tools"><p><strong>10 directions</strong> · Each is a working prototype</p><div><button class="shortlist-filter" aria-pressed="false">Show shortlist <span data-shortlist-count>0</span></button><button class="compare-launch" disabled>Compare selected <span data-compare-count>0 / 2</span></button></div></div><p class="shortlist-empty" hidden>No shortlisted directions yet. Use the star on any direction to save it here.</p><section class="directions-grid" aria-label="Design directions">'''+''.join(cards)+'''</section><section class="review-notes"><h2>Pick the feeling.<br>Then we refine the details.</h2><div><p>The goal is to choose a direction, or a useful combination: one design’s typography, another’s project presentation, a third’s tone.</p><p>Your shortlist stays in this browser. Prototype forms do not submit or store inquiries. The live East Bay Projects site is unchanged.</p></div></section></main><footer class="lab-footer lab-wrap"><span>East Bay Projects / Design exploration</span><a href="https://eastbayprojects.com/" target="_blank" rel="noopener noreferrer">Current live site ↗</a></footer></body></html>'''
(OUT/'index.html').write_text(gallery)
opts=''.join(f'<option value="{c["id"]}">{c["number"]} · {c["name"]}</option>' for c in CONCEPTS)
compare=head('Compare Directions','explore.css')+f'''<body class="comparison"><header class="compare-header"><a href="/directions.html">↖ All directions</a><h1>Side by side.</h1><div class="compare-sizes" role="group" aria-label="Preview width"><button data-frame-size="desktop" aria-pressed="true">Desktop</button><button data-frame-size="phone" aria-pressed="false">Phone</button></div></header><main class="compare-grid"><section class="compare-pane"><div class="pane-toolbar"><label>Left direction <select data-compare-side="left">{opts}</select></label><a data-open-side="left" href="/editorial/" target="_blank">Open ↗</a></div><div class="frame-stage"><iframe title="Left design preview" data-frame="left" src="/editorial/?embed=1"></iframe></div></section><section class="compare-pane"><div class="pane-toolbar"><label>Right direction <select data-compare-side="right">{opts}</select></label><a data-open-side="right" href="/swiss/" target="_blank">Open ↗</a></div><div class="frame-stage"><iframe title="Right design preview" data-frame="right" src="/swiss/?embed=1"></iframe></div></section></main><p class="compare-note">Scroll each preview independently. Use Open to explore a direction at full width.</p></body></html>'''
